192	export async function createIssue(
193	  actor: Actor,
194	  input: CreateIssueInput,
195	): Promise<Issue> {
196	  assertOrgScope(actor, input.orgId);
197	
198	  const project = requireFound(
199	    await projectRepo.findProjectById(input.orgId, input.projectId),
200	    "Project",
201	    input.projectId,
202	  );
203	  assertNotArchived("Project", project.id, project);
204	  assertCan(actor, "issue:create", projectResource(project));
205	
206	  const org = requireFound(
207	    await orgRepo.findOrgById(input.orgId),
208	    "Organization",
209	    input.orgId,
210	  );
211	  const used = await issueRepo.countIssues(input.orgId, input.projectId);
212	  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
213	    throw new Error(
214	      `Plan ${org.plan} allows no more issues in project ${project.key}`,
215	    );
216	  }
217	
218	  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
219	  const issue = await issueRepo.insertIssue(input, actor.userId, number);
220	
221	  await emit("issue.created", {
222	    ...actorEnvelope(actor),
223	    issueId: issue.id,
224	    projectId: issue.projectId,
225	    title: issue.title,
226	    assigneeId: issue.assigneeId,
227	    priority: issue.priority,
228	  });
229	
230	  return issue;
231	}
