735	 * parsed out of the body server-side. The server list wins on disagreement.
736	 */
737	async function resolveMentionedUsers(
738	  orgId: OrgId,
739	  body: string,
740	  clientProvided: readonly UserId[],
741	): Promise<readonly UserId[]> {
742	  const members = await memberRepo.listMembers({
