795	/**
796	 * Writes one notification row per recipient, each with the channel set that
797	 * recipient's preferences allow. A recipient who has muted every channel is
798	 * skipped entirely rather than given a row nobody will ever see.
799	 */
800	export async function notify(
801	  orgId: OrgId,
802	  kind: NotificationKind,
803	  recipients: readonly UserId[],
804	  payload: NotificationPayload,
805	): Promise<readonly Notification[]> {
806	  if (recipients.length === 0) return [];
807	
808	  const org = await orgRepo.findOrgById(orgId);
809	  const flags: FlagContext = {
810	    orgId,
811	    userId: payload.actorId,
812	    plan: org?.plan ?? "free",
813	    role: null,
814	    overrides: org?.settings.enabledFlagOverrides,
815	  };
816	
817	  const rows = [];
818	
819	  for (const recipientId of new Set(recipients)) {
820	    if (recipientId === payload.actorId) continue;
821	
822	    const preference = await preferenceRepo.getPreference(
823	      orgId,
824	      recipientId,
825	      kind,
826	    );
827	    const channels = resolveChannels(preference, flags);
828	    if (channels.length === 0) continue;
829	
830	    rows.push({
831	      orgId,
