904	
905	/**
906	 * Turns a stored preference into the channels one notification will use.
907	 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
908	 * the email channel additionally requires the org's `digest_email` plan flag.
909	 */
910	export function resolveChannels(
911	  preference: NotificationPreference | null,
912	  flags: FlagContext,
913	): readonly NotificationChannel[] {
914	  if (preference === null) return DEFAULT_CHANNELS;
915	
916	  const channels: NotificationChannel[] = [];
917	  if (preference.inApp) channels.push("in_app");
918	
919	  const emailAllowed =
920	    preference.email &&
921	    (!preference.digestOnly || isEnabled("digest_email", flags));
922	
923	  if (emailAllowed) channels.push("email");
924	  return channels;
