927	/**
928	 * The bus wiring. Attached at module load rather than from `event-registry`
929	 * because the fan-out has no other public entry point — importing this module
930	 * is what makes an org start receiving notifications.
931	 */
932	let registered = false;
933	
934	function registerFanOut(): void {
935	  if (registered) return;
936	  registered = true;
937	
938	  subscribe("issue.assigned", async (payload) => {
939	    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
940	      title: "You were assigned an issue",
941	      body: `Issue ${payload.issueId} is now yours`,
942	      href: `/issues/${payload.issueId}`,
