/** One absence per (org, user): writing again replaces the previous one. */
export async function upsertAbsence(
  absence: MemberAbsence,
): Promise<MemberAbsence> {
  const stamp = toIsoTimestamp(new Date());
  const values = {
    delegateUserId: absence.delegateUserId,
    startsAt: absence.startsAt,
    endsAt: absence.endsAt,
    note: absence.note,
    updatedAt: stamp,
  };
  const row = getDb()
    .insert(memberAbsences)
    .values({
      orgId: absence.orgId,
      userId: absence.userId,
      createdAt: stamp,
      ...values,
    })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: values,
    })
    .returning()
    .get();
  return toMemberAbsence(row);
}

