/**
 * Marks a member out of office from `startsAt` (inclusive) to `endsAt`
 * (exclusive), optionally naming a stand-in. Replaces any absence already set.
 */
export async function setAbsence(
  actor: Actor,
  input: SetAbsenceInput,
): Promise<MemberAbsence> {
  assertOrgScope(actor, input.orgId);

  const member = await requireActiveMember(input.orgId, input.userId);
  assertCanManageAbsence(actor, member);

  const startsAt = Date.parse(input.startsAt);
  const endsAt = Date.parse(input.endsAt);
  if (Number.isNaN(startsAt) || Number.isNaN(endsAt)) {
    throw new Error("An absence needs a valid start and end");
  }
  if (endsAt <= startsAt) {
    throw new Error("An absence must end after it starts");
  }

  const note = input.note ?? null;
  if (note !== null && note.length > 200) {
    throw new Error("An absence note may be at most 200 characters");
  }

  const delegateUserId = input.delegateUserId ?? null;
  if (delegateUserId !== null) {
    if (delegateUserId === input.userId) {
      throw new Error("A member cannot be their own delegate");
    }
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return memberRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note,
  });
}

