  const absence = await memberRepo.findAbsence(orgId, userId);
  if (absence === null) return null;
  return Date.now() < Date.parse(absence.endsAt) ? absence : null;
}

/**
 * Who stands in for `userId` at the instant `at`: their delegate when they
 * are away right then and the delegate is still an active member, otherwise
 * `null`. Never chained — the delegate's own absence is not consulted.
 */
export async function findActiveDelegate(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await memberRepo.findAbsence(orgId, userId);
  if (absence === null || absence.delegateUserId === null) return null;
  if (absence.delegateUserId === userId) return null;

  const moment = at.getTime();
  if (
    Number.isNaN(moment) ||
    moment < Date.parse(absence.startsAt) ||
    moment >= Date.parse(absence.endsAt)
  ) {
    return null;
  }

  for (const id of [userId, absence.delegateUserId]) {
    const member = await memberRepo.findMember(orgId, id);
    if (member === null || member.status !== "active") return null;
  }
  return absence.delegateUserId;
}

